<script setup lang="ts">
import type {Job} from '../../shared/types'
const props=defineProps<{job:Job}>()
const latest=computed(()=>props.job.attempts?.[props.job.attempts.length-1])
const failure=computed(()=>[...(props.job.attempts||[])].reverse().find(a=>a.diagnostic))
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(props.job,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=props.job.problemId+'-generation-'+props.job.id.slice(0,8)+'.json';a.click();URL.revokeObjectURL(url)}
</script>
<template><div class="generation-status"><a-alert :type="job.state==='failed'?'error':job.state==='done'?'success':'info'" :message="job.message" show-icon/><div class="generation-request-meta"><span v-if="job.model">{{job.model}}</span><span v-if="job.reasoningMode">{{job.reasoningMode==='off'?'未发送思考参数':'请求强度：'+job.reasoningEffort}}</span><span v-if="job.attempts?.length">第 {{job.attempts.length}} 次调用</span><span v-if="latest?.completion?.reasoningObserved">API 返回思考内容</span><span v-if="latest?.completion?.reasoningTokens!==undefined">思考 Token：{{latest.completion.reasoningTokens}}</span></div><a-collapse v-if="failure?.diagnostic" :bordered="false"><a-collapse-panel key="error" header="校验失败详情"><div class="generation-error-details"><strong>{{failure.diagnostic.stage}}</strong><p>{{failure.diagnostic.message}}</p><template v-if="failure.diagnostic.input"><div class="io-label">出错输入</div><pre>{{failure.diagnostic.input}}</pre></template><template v-if="failure.diagnostic.referenceOutput!==undefined"><div class="io-label">参考解输出</div><pre>{{failure.diagnostic.referenceOutput}}</pre></template><template v-if="failure.diagnostic.checkerOutput!==undefined"><div class="io-label">第二份解法输出</div><pre>{{failure.diagnostic.checkerOutput}}</pre></template><template v-if="failure.diagnostic.expectedOutput!==undefined"><div class="io-label">公开样例标准答案</div><pre>{{failure.diagnostic.expectedOutput}}</pre></template></div></a-collapse-panel></a-collapse><button v-if="job.attempts?.length" class="text-button" @click="download">下载生成记录与脚本</button></div></template>
